import { motionLimits } from "./motion";

/** Internal pure planning only. S10 owns DOM eligibility, rendering and distribution. */
export interface TextUnit {
  readonly identity: object;
  readonly text: string;
}
export interface TextSnapshot {
  readonly value: string;
  readonly units: readonly TextUnit[] | null;
  readonly unavailable?: "segmenter" | "input";
}
/** Presentation groups only: never changes retained grapheme identities or DOM. */
export function changedTextGroups(
  snapshot: TextSnapshot,
  incoming: readonly TextUnit[],
  word: boolean,
  locale?: string,
) {
  const groups = new Map<object, number>();
  if (!word) {
    for (const unit of incoming) groups.set(unit.identity, groups.size);
    return groups;
  }
  if (!snapshot.units || typeof Intl.Segmenter !== "function") return null;
  try {
    const changed = new Set(incoming.map((unit) => unit.identity));
    const segments = new Intl.Segmenter(locale, { granularity: "word" }).segment(snapshot.value);
    let index = 0,
      offset = 0,
      group = 0;
    for (const segment of segments) {
      let used = false;
      const end = segment.index + segment.segment.length;
      while (index < snapshot.units.length && offset < end) {
        const unit = snapshot.units[index++];
        if (!unit) break;
        if (changed.has(unit.identity)) {
          groups.set(unit.identity, group);
          used = true;
        }
        offset += unit.text.length;
      }
      if (used) group++;
    }
    return groups;
  } catch {
    return null;
  }
}

export interface TextChangeRun {
  readonly outgoing: readonly TextUnit[];
  readonly incoming: readonly TextUnit[];
  /** UTF-16 offsets in the exact before/after strings, for shaping-boundary proof. */
  readonly before: readonly [number, number];
  readonly after: readonly [number, number];
}
type Fallback = "segmenter" | "input" | "comparisons" | "changed" | "shaping" | "native";
export interface TextDiff {
  readonly snapshot: TextSnapshot;
  readonly runs: readonly TextChangeRun[];
  readonly comparisons: number;
  readonly path: "baseline" | "equal" | "append" | "trim" | "middle";
  /** A null reason is a diff candidate, never permission to split a DOM tree. */
  readonly immediate: Fallback | null;
}

function unit(text: string): TextUnit {
  return { identity: {}, text };
}

export function createTextSnapshot(value: string, locale?: string): TextSnapshot {
  if (typeof Intl.Segmenter !== "function") return { value, units: null, unavailable: "segmenter" };
  try {
    const segments = new Intl.Segmenter(locale, { granularity: "grapheme" }).segment(value);
    const units: TextUnit[] = [];
    for (const { segment } of segments) {
      // Stop on the first excess item; never materialize an oversized iterator.
      if (units.length === motionLimits.diffInput) return { value, units: null, unavailable: "input" };
      units.push(unit(segment));
    }
    return { value, units };
  } catch {
    // Missing locale/segmenter support is exact output, never code-point splitting.
    return { value, units: null, unavailable: "segmenter" };
  }
}

/** Prefix/append + suffix-biased trimming, then a strictly bounded LCS middle. */
export function diffText(previous: TextSnapshot, value: string, locale?: string): TextDiff {
  const result = (snapshot: TextSnapshot, immediate: Fallback | null, path: TextDiff["path"]): TextDiff => ({
    snapshot,
    immediate,
    path,
    runs: [],
    comparisons: 0,
  });
  if (previous.value === value) return result(previous, previous.unavailable ?? null, "equal");
  const next = createTextSnapshot(value, locale);
  if (!next.units || !previous.units)
    return result(next, next.unavailable ?? previous.unavailable ?? "segmenter", "baseline");
  const old = previous.units;
  const incoming = [...next.units];
  let prefix = 0;
  while (prefix < old.length && prefix < incoming.length && old[prefix]?.text === incoming[prefix]?.text) prefix++;
  const append = prefix === old.length;
  let suffix = 0;
  if (!append) {
    while (
      suffix < old.length &&
      suffix < incoming.length &&
      old[old.length - 1 - suffix]?.text === incoming[incoming.length - 1 - suffix]?.text
    )
      suffix++;
    // In ambiguous repeated text, preserve the original suffix (aba -> aaba).
    prefix = Math.min(prefix, old.length - suffix, incoming.length - suffix);
  }
  const matches: [number, number][] = [];
  for (let index = 0; index < prefix; index++) matches.push([index, index]);
  const rows = old.length - prefix - suffix;
  const columns = incoming.length - prefix - suffix;
  const path = append ? "append" : rows && columns ? "middle" : "trim";
  let comparisons = 0;
  const overflow = rows * columns > motionLimits.diffComparisons;
  if (!overflow && rows && columns) {
    // The table has at most 4096 comparison cells, plus its bounded sentinel edges.
    const stride = columns + 1;
    const lcs = new Uint16Array((rows + 1) * stride);
    for (let row = rows - 1; row >= 0; row--) {
      for (let column = columns - 1; column >= 0; column--) {
        comparisons++;
        lcs[row * stride + column] =
          old[prefix + row]?.text === incoming[prefix + column]?.text
            ? 1 + (lcs[(row + 1) * stride + column + 1] ?? 0)
            : Math.max(lcs[(row + 1) * stride + column] ?? 0, lcs[row * stride + column + 1] ?? 0);
      }
    }
    let row = 0;
    let column = 0;
    while (row < rows && column < columns) {
      // Read the table, not a second round of candidate text comparisons.
      const current = lcs[row * stride + column] ?? 0;
      if (current === (lcs[row * stride + column + 1] ?? 0)) column++;
      else if (current === (lcs[(row + 1) * stride + column] ?? 0)) row++;
      else {
        matches.push([prefix + row++, prefix + column++]);
      }
    }
  }
  for (let index = suffix; index > 0; index--) matches.push([old.length - index, incoming.length - index]);
  for (const [before, after] of matches) incoming[after] = old[before] as TextUnit;
  const snapshot: TextSnapshot = { value, units: incoming };
  if (overflow) return result(snapshot, "comparisons", path);

  const runs: TextChangeRun[] = [];
  let before = 0;
  let after = 0;
  let beforeOffset = 0;
  let afterOffset = 0;
  for (const [oldIndex, newIndex] of [...matches, [old.length, incoming.length] as [number, number]]) {
    const outgoing = old.slice(before, oldIndex);
    const arriving = incoming.slice(after, newIndex);
    const beforeEnd = beforeOffset + outgoing.reduce((sum, item) => sum + item.text.length, 0);
    const afterEnd = afterOffset + arriving.reduce((sum, item) => sum + item.text.length, 0);
    if (outgoing.length || arriving.length)
      runs.push({ outgoing, incoming: arriving, before: [beforeOffset, beforeEnd], after: [afterOffset, afterEnd] });
    beforeOffset = beforeEnd + (old[oldIndex]?.text.length ?? 0);
    afterOffset = afterEnd + (incoming[newIndex]?.text.length ?? 0);
    before = oldIndex + 1;
    after = newIndex + 1;
  }
  const changed = runs.reduce((sum, run) => sum + run.outgoing.length + run.incoming.length, 0);
  return {
    snapshot,
    runs: changed > motionLimits.changedGraphemes ? [] : runs,
    comparisons,
    path,
    immediate: changed > motionLimits.changedGraphemes ? "changed" : null,
  };
}

/**
 * An adapter must prove these boundaries against the actual typography/layout.
 * Grapheme/word segmentation alone is NOT that proof (including Latin ligatures).
 * Native/inherited editing and unknown correspondence must never supply a proof.
 */
export function shapeTextDiff(
  diff: TextDiff,
  proof?: { readonly before: ReadonlySet<number>; readonly after: ReadonlySet<number> },
  native = false,
): TextDiff {
  if (native) return { ...diff, runs: [], immediate: "native" };
  if (diff.immediate || diff.runs.length === 0) return diff;
  if (
    !proof ||
    diff.runs.some(
      (run) =>
        run.before.some((offset) => !proof.before.has(offset)) || run.after.some((offset) => !proof.after.has(offset)),
    )
  )
    return { ...diff, runs: [], immediate: "shaping" };
  return diff;
}

/** Pure preflight; the S06 transaction remains the sole lifecycle/work owner. */
export function boundTextRevision(
  diffs: readonly TextDiff[],
  active: ReadonlySet<object> = new Set(),
): readonly TextDiff[] {
  const identities = new Set<object>();
  const add = (identity: object) => {
    identities.add(identity);
    return identities.size <= motionLimits.changedGraphemes;
  };
  let fits = true;
  for (const identity of active) {
    if (!add(identity)) {
      fits = false;
      break;
    }
  }
  if (fits)
    outer: for (const diff of diffs) {
      for (const run of diff.runs) {
        for (const item of [...run.outgoing, ...run.incoming]) {
          if (!add(item.identity)) {
            fits = false;
            break outer;
          }
        }
      }
    }
  return fits ? diffs : diffs.map((diff) => ({ ...diff, runs: [], immediate: diff.immediate ?? "changed" }));
}

import { type CadenceMode, textProofLimits } from "./motion";
import { knownTextGeometry } from "./motion-transaction";
import type { TextSnapshot, TextUnit } from "./text-diff";

type Box = Pick<DOMRect, "left" | "top" | "width" | "height">;
const highlights = new WeakMap<Document, Set<Highlight>>();
/** Trusted pixel-only text/reel masks share a document registry. Unknown caller
 * highlights still force native paint; one family's mask is not foreign work. */
export function ownedTextHighlights(doc: Document) {
  let known = highlights.get(doc);
  if (!known) {
    known = new Set<Highlight>();
    highlights.set(doc, known);
  }
  return known;
}

export type TextLayout = {
  boxes: Map<object, Box>;
  font: string;
  color: string;
  ascent: number;
  descent: number;
  baseline: number;
  kerning: CanvasFontKerning;
};

/** Actual inherited editing, including plaintext-only and explicit false islands. */
export function nativeTextContext(host: HTMLElement) {
  if (host.ownerDocument.designMode === "on" || host.isContentEditable) return true;
  for (let node: HTMLElement | null = host; node; node = node.parentElement) {
    const value = node.getAttribute("contenteditable")?.toLowerCase();
    if (value === "false") return false;
    if (value === "" || value === "true" || value === "plaintext-only") return true;
  }
  return Boolean(host.closest("input,textarea,select,option"));
}

export function selectedTextContext(host: HTMLElement) {
  const selection = host.ownerDocument.getSelection();
  if (!selection || selection.isCollapsed) return false;
  for (let index = 0; index < selection.rangeCount; index++) {
    if (selection.getRangeAt(index).intersectsNode(host)) return true;
  }
  return false;
}

/** These CSS paint properties change neither glyph ink nor its coordinate map.
 * Foreground, opacity, layout and unknown engine properties stay fail-closed. */
export function textSurfacePaint(property: string) {
  return /^(background-color|border-(top|right|bottom|left)-color|box-shadow)$/.test(
    property.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`),
  );
}
export function surfaceOnlyAnimation(animation: Animation) {
  const frames = (animation.effect as KeyframeEffect | null)?.getKeyframes?.();
  if (!frames?.length) return false;
  const properties = frames.flatMap((frame) =>
    Object.keys(frame).filter((key) => !["offset", "computedOffset", "easing", "composite"].includes(key)),
  );
  return properties.length > 0 && properties.every(textSurfacePaint);
}

/** Conservative actual-font raster correspondence, never an ASCII-only proof.
 * Unsupported scripts/features remain exact native text. No typography overrides.
 */
export function proveTextLayout(
  host: HTMLElement,
  snapshot: TextSnapshot,
  { surfacePaint = false, geometryMode }: { surfacePaint?: boolean; geometryMode?: CadenceMode } = {},
): TextLayout | null {
  const view = host.ownerDocument.defaultView;
  const css = view?.getComputedStyle(host);
  const viewport = view?.visualViewport;
  if (
    // Native/canvas glyph coverage is proven at unit device scale only.
    // Other scales keep exact native text until that correspondence is proven.
    view?.devicePixelRatio !== 1 ||
    (viewport && (viewport.scale !== 1 || viewport.offsetLeft !== 0 || viewport.offsetTop !== 0)) ||
    !css ||
    !snapshot.units ||
    !host.isConnected ||
    host.textContent !== snapshot.value ||
    nativeTextContext(host) ||
    selectedTextContext(host) ||
    host.closest('[hidden],[inert],[aria-hidden="true"]') ||
    css.visibility !== "visible" ||
    css.display === "none" ||
    css.opacity !== "1" ||
    css.direction !== "ltr" ||
    css.writingMode !== "horizontal-tb" ||
    css.textTransform !== "none" ||
    css.textShadow !== "none" ||
    css.textDecorationLine !== "none" ||
    !["normal", "0px"].includes(css.letterSpacing) ||
    !["normal", "0px"].includes(css.wordSpacing) ||
    css.fontFeatureSettings !== "normal" ||
    css.fontVariationSettings !== "normal" ||
    css.fontVariant !== "normal" ||
    !css.font ||
    /[^\x20-\x7e]/.test(snapshot.value) ||
    !host.ownerDocument.fonts?.check(css.font, snapshot.value || " ")
  )
    return null;
  for (let node: HTMLElement | null = host; node; node = node.parentElement) {
    const style = view.getComputedStyle(node);
    if (
      style.visibility !== "visible" ||
      style.display === "none" ||
      style.opacity !== "1" ||
      (style.transform !== "none" &&
        (() => {
          // Native popup placement is a stable translation, not glyph scaling.
          // Range boxes already contain that viewport mapping. Active transforms
          // remain rejected by the animation check below and layout invalidation.
          const matrix = new DOMMatrixReadOnly(style.transform);
          return !matrix.is2D || matrix.a !== 1 || matrix.d !== 1 || matrix.b !== 0 || matrix.c !== 0;
        })()) ||
      style.translate !== "none" ||
      style.scale !== "none" ||
      style.rotate !== "none" ||
      style.filter !== "none" ||
      style.perspective !== "none" ||
      style.backdropFilter !== "none" ||
      style.clipPath !== "none" ||
      style.maskImage !== "none" ||
      /layout|paint|strict|content/.test(style.contain) ||
      style.contentVisibility !== "visible" ||
      /transform|filter|perspective/.test(style.willChange) ||
      !["normal", "1"].includes(style.zoom) ||
      node
        .getAnimations()
        .some(
          (animation) =>
            !knownTextGeometry(animation, geometryMode) && (!surfacePaint || !surfaceOnlyAnimation(animation)),
        )
    )
      return null;
  }
  const canvas = host.ownerDocument.createElement("canvas");
  const context = canvas.getContext("2d", { willReadFrequently: true });
  if (!context) return null;
  context.font = css.font;
  context.fontKerning = css.fontKerning as CanvasFontKerning;
  const metrics = context.measureText(snapshot.value);
  const padding = Math.ceil(Number.parseFloat(css.fontSize));
  const ascent = metrics.fontBoundingBoxAscent,
    descent = metrics.fontBoundingBoxDescent;
  const width = Math.ceil(metrics.width) + padding * 2;
  const height = Math.ceil(ascent + descent) + padding * 2;
  if (
    ![width, height, ascent, descent].every(Number.isFinite) ||
    width <= 0 ||
    height <= 0 ||
    width > textProofLimits.axis ||
    height > textProofLimits.axis ||
    width * height > textProofLimits.pixels
  )
    return null;
  canvas.width = width;
  canvas.height = height;
  context.font = css.font;
  context.fontKerning = css.fontKerning as CanvasFontKerning;
  context.fillText(snapshot.value, padding, padding + ascent);
  const whole = context.getImageData(0, 0, width, height).data;
  context.clearRect(0, 0, width, height);
  let x = padding;
  for (const unit of snapshot.units) {
    context.fillText(unit.text, x, padding + ascent);
    x += context.measureText(unit.text).width;
  }
  const separate = context.getImageData(0, 0, width, height).data;
  if (whole.some((value, index) => value !== separate[index])) return null;
  const boxes = new Map<object, Box>();
  let offset = 0;
  for (const unit of snapshot.units) {
    const text = host.firstChild;
    if (text?.nodeType !== 3) return null;
    const range = host.ownerDocument.createRange();
    const start = offset;
    range.setStart(text, start);
    range.setEnd(text, start + unit.text.length);
    const rects = range.getClientRects();
    if (rects.length !== 1) return null;
    const box = rects[0];
    if (!box || ![box.left, box.top, box.width, box.height].every(Number.isFinite) || box.height <= 0) return null;
    boxes.set(unit.identity, { left: box.left, top: box.top, width: box.width, height: box.height });
    offset += unit.text.length;
  }
  let baseline = ascent;
  if (snapshot.units.length) {
    // Canvas font bounding metrics can round differently from native line boxes
    // at fractional device scales. A zero-size, empty baseline probe measures
    // the REAL line baseline, never a second content tree or a glyph wrapper.
    const original = [...host.getClientRects()].map((box) => [box.left, box.top, box.width, box.height].join("/"));
    const probe = host.ownerDocument.createElement("span");
    probe.setAttribute("aria-hidden", "true");
    probe.style.cssText =
      "all:initial;display:inline-block;width:0;height:0;line-height:0;vertical-align:baseline;border:0;padding:0;margin:0";
    host.append(probe);
    const top = probe.getBoundingClientRect().top;
    const current = [...host.getClientRects()].map((box) => [box.left, box.top, box.width, box.height].join("/"));
    probe.remove();
    if (original.length !== current.length || original.some((box, index) => box !== current[index])) return null;
    const last = boxes.get(snapshot.units[snapshot.units.length - 1]?.identity ?? {});
    if (!last) return null;
    baseline = top - last.top;
    if (!Number.isFinite(baseline) || baseline <= 0 || baseline > last.height) return null;
  }
  return {
    boxes,
    font: css.font,
    color: css.color,
    ascent,
    descent,
    baseline,
    kerning: css.fontKerning as CanvasFontKerning,
  };
}

let nextLayoutAnchor = 0;
/** Native coordinate transport, not an animated position owner. Preserve the
 * single native Text tree while fixed pixel layers follow an intrinsic shell. */
export function followTextLayout(host: HTMLElement, layer: HTMLElement, revoke: () => void): (() => void) | null {
  const doc = host.ownerDocument,
    view = doc.defaultView;
  const attribute = "data-cadence-layout-anchor";
  if (
    !view?.CSS.supports("anchor-name", "--cadence-display") ||
    !view.CSS.supports("left", "anchor(--cadence-display left)") ||
    host.getRootNode() !== doc ||
    host.hasAttribute(attribute) ||
    view.getComputedStyle(host).getPropertyValue("anchor-name") !== "none"
  )
    return null;
  const id = String(++nextLayoutAnchor),
    name = `--cadence-display-${id}`;
  const sheet = new view.CSSStyleSheet();
  const origin = host.getBoundingClientRect();
  let alive = true;
  const observer = new MutationObserver(() => {
    if (alive && host.getAttribute(attribute) !== id) revoke();
  });
  const dispose = () => {
    alive = false;
    observer.disconnect();
    if (host.getAttribute(attribute) === id) host.removeAttribute(attribute);
    doc.adoptedStyleSheets = doc.adoptedStyleSheets.filter((value) => value !== sheet);
  };
  try {
    sheet.replaceSync(`[${attribute}="${id}"] { anchor-name: ${name}; }`);
    doc.adoptedStyleSheets = [...doc.adoptedStyleSheets, sheet];
    host.setAttribute(attribute, id);
    layer.style.left = `anchor(${name} left)`;
    layer.style.top = `anchor(${name} top)`;
    // Check the actual containing tree/scope, not CSS.supports alone.
    const mapped = layer.getBoundingClientRect();
    if (
      view.getComputedStyle(host).getPropertyValue("anchor-name") !== name ||
      Math.abs(mapped.left - origin.left) > textProofLimits.coordinateUnit ||
      Math.abs(mapped.top - origin.top) > textProofLimits.coordinateUnit
    ) {
      dispose();
      return null;
    }
    // Native anchor coordinates quantize to a layout unit, while a projected
    // getBoundingClientRect can retain finer precision. Cancel that measured
    // initial offset; larger/different mappings still fail closed above.
    layer.style.left = `calc(anchor(${name} left) - ${mapped.left}px)`;
    layer.style.top = `calc(anchor(${name} top) - ${mapped.top}px)`;
    observer.observe(host, { attributes: true, attributeFilter: [attribute] });
    return dispose;
  } catch {
    dispose();
    return null;
  }
}

/** Candidate pixels must fit the original overflow clip, including used rounded
 * corners. CSS scales all corner radii by one factor before subtracting borders.
 * No clipping tree or typography is cloned; unknown shapes stay native. */
function insideTextClips(host: HTMLElement, box: Box) {
  const view = host.ownerDocument.defaultView;
  if (!view) return false;
  for (let node: HTMLElement | null = host; node; node = node.parentElement) {
    const css = view.getComputedStyle(node);
    if (!/(auto|scroll|hidden|clip)/.test(`${css.overflowX} ${css.overflowY}`)) continue;
    const outer = node.getBoundingClientRect();
    const borders = [css.borderLeftWidth, css.borderTopWidth, css.borderRightWidth, css.borderBottomWidth].map(
      Number.parseFloat,
    ) as [number, number, number, number];
    if (
      borders.some((value) => !Number.isFinite(value)) ||
      node.clientLeft !== Math.round(borders[0]) ||
      node.clientTop !== Math.round(borders[1])
    )
      return false;
    const left = outer.left + borders[0],
      top = outer.top + borders[1];
    const width = Math.min(node.clientWidth, outer.width - borders[0] - borders[2]);
    const height = Math.min(node.clientHeight, outer.height - borders[1] - borders[3]);
    if (box.left < left || box.top < top || box.left + box.width > left + width || box.top + box.height > top + height)
      return false;
    const length = (value: string, size: number) => {
      if (!/^(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?(?:px|%)?$/.test(value)) return NaN;
      return Number.parseFloat(value) * (value.endsWith("%") ? size / 100 : 1);
    };
    const radius = (value: string): [number, number] => {
      const [x = "", y = x] = value.split(/\s+/);
      return [length(x, outer.width), length(y, outer.height)];
    };
    const corners = [
      radius(css.borderTopLeftRadius),
      radius(css.borderTopRightRadius),
      radius(css.borderBottomRightRadius),
      radius(css.borderBottomLeftRadius),
    ] as const;
    if (corners.flat().some((value) => !Number.isFinite(value))) return false;
    const factor = Math.min(
      1,
      outer.width / (corners[0][0] + corners[1][0]),
      outer.width / (corners[3][0] + corners[2][0]),
      outer.height / (corners[0][1] + corners[3][1]),
      outer.height / (corners[1][1] + corners[2][1]),
    );
    if (!Number.isFinite(factor)) return false;
    const radii = corners.map(([x, y], i): [number, number] => [
      Math.max(0, x * factor - borders[i === 0 || i === 3 ? 0 : 2]),
      Math.max(0, y * factor - borders[i < 2 ? 1 : 3]),
    ]);
    for (const x of [box.left - left, box.left + box.width - left])
      for (const y of [box.top - top, box.top + box.height - top]) {
        for (const [i, [rx, ry]] of radii.entries()) {
          const dx = Math.max(0, rx - (i === 0 || i === 3 ? x : width - x));
          const dy = Math.max(0, ry - (i < 2 ? y : height - y));
          if (rx > 0 && ry > 0 && dx > 0 && dy > 0 && (dx / rx) ** 2 + (dy / ry) ** 2 > 1) return false;
        }
      }
  }
  return true;
}

/** Paint contains pixels only: no outgoing accessible/selectable/findable string. */
export function outgoingTextPaint(host: HTMLElement, unit: TextUnit, layout: TextLayout, alignPixels = false) {
  const box = layout.boxes.get(unit.identity);
  if (!box || box.width <= 0) return null;
  const canvas = host.ownerDocument.createElement("canvas");
  const ratio = host.ownerDocument.defaultView?.devicePixelRatio ?? 1;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.font = layout.font;
  const metrics = context.measureText(unit.text);
  const inkLeft = Math.min(box.left, box.left - metrics.actualBoundingBoxLeft);
  const inkRight = Math.max(box.left + box.width, box.left + metrics.actualBoundingBoxRight);
  const inkTop = alignPixels ? box.top : Math.min(box.top, box.top + layout.baseline - metrics.actualBoundingBoxAscent);
  const inkBottom = alignPixels
    ? box.top + box.height
    : Math.max(box.top + box.height, box.top + layout.baseline + metrics.actualBoundingBoxDescent);
  if (!insideTextClips(host, { left: inkLeft, top: inkTop, width: inkRight - inkLeft, height: inkBottom - inkTop }))
    return null;
  const padding =
    Math.ceil(
      Math.max(
        0,
        metrics.actualBoundingBoxLeft,
        metrics.actualBoundingBoxRight - box.width,
        metrics.actualBoundingBoxAscent - layout.baseline,
        metrics.actualBoundingBoxDescent - (box.height - layout.baseline),
      ),
    ) + 1;
  // A numeric cell can start at a fractional layout coordinate. Keep its canvas
  // texture on the device-pixel grid and raster the actual glyph offset inside
  // it; translating an integer-origin raster would resample its resting glyph.
  const left = alignPixels ? Math.floor((box.left - padding) * ratio) / ratio : box.left - padding;
  const top = alignPixels ? Math.floor((box.top - padding) * ratio) / ratio : box.top - padding;
  const width = Math.ceil((box.left + box.width + padding - left) * ratio),
    height = Math.ceil((box.top + box.height + padding - top) * ratio);
  if (width * height > textProofLimits.pixels || Math.max(width, height) > textProofLimits.axis) return null;
  canvas.width = width;
  canvas.height = height;
  context.scale(ratio, ratio);
  context.font = layout.font;
  context.fontKerning = layout.kerning;
  context.fillStyle = layout.color;
  context.fillText(unit.text, box.left - left, box.top - top + layout.baseline);
  Object.assign(canvas.style, {
    position: "absolute",
    left: `${left}px`,
    top: `${top}px`,
    width: `${width / ratio}px`,
    height: `${height / ratio}px`,
    pointerEvents: "none",
    userSelect: "none",
  });
  canvas.setAttribute("aria-hidden", "true");
  canvas.dataset.cadenceTextPaint = "";
  return canvas;
}

"use client";

import type { createCapturedHandoff } from "./captured-handoff";
import {
  bindMotionParameters,
  handoffValue,
  motionLimits,
  motionMilliseconds,
  resolveStaggerParameters,
  textProofLimits,
  textReplace,
} from "./motion";
import { type MotionEnvironment, subscribeMotionEnvironment } from "./motion-environment";
import {
  createMotionTransaction,
  knownTextGeometry,
  type MotionLease,
  type MotionRevision,
  textGeometryProperties,
} from "./motion-transaction";
import type { CadenceMotion } from "./provider";
import { boundTextRevision, changedTextGroups, createTextSnapshot, diffText, shapeTextDiff } from "./text-diff";
import {
  followTextLayout,
  nativeTextContext,
  outgoingTextPaint,
  ownedTextHighlights,
  proveTextLayout,
  selectedTextContext,
  surfaceOnlyAnimation,
  textSurfacePaint,
} from "./text-layout";

const binding = bindMotionParameters(textReplace, "text.change/changed-runs");
type Capture = Parameters<ReturnType<typeof createCapturedHandoff>["commit"]>[0]["capture"];
let nextMask = 0;
export interface TextPresentationCommit {
  value: string;
  revision: MotionRevision;
  cm: CadenceMotion;
  /** The native owner's existing semantic slot/entity identity. */
  entity: unknown;
  locale?: string;
  granularity?: "auto" | "grapheme" | "word";
  characterStagger?: boolean;
  visible?: boolean;
  capture?: Capture;
  sourceRetired?: boolean;
  /** Compound Select commits its sole size owner before claiming destination paint. */
  deferHandoff?: boolean;
  /** Expected prior display when a compound primitive changes renderer in an editor. */
  nativeBaseline?: string;
  /** Final-width selection-strip adapter; authority still requires real current leases. */
  stripGeometry?: boolean;
}

/** Internal plain-string boundary. One native Text node; no child traversal,
 * semantic decomposition, per-frame layout reads or independent geometry owner.
 * Adapter owns explicit commits and physical disposal, never a removal scanner.
 */
export function createTextPresentation(
  host: HTMLElement,
  transaction = createMotionTransaction(),
  /** Native composition supplies a dedicated coordinator only when it owns origins.
   * This controller disposes it; ordinary text never reaches the handoff engine. */
  handoff?: ReturnType<typeof createCapturedHandoff>,
  sharedHandoff = false,
) {
  const registration = transaction.register(host);
  const doc = host.ownerDocument,
    view = doc.defaultView;
  const highlights = view?.CSS?.highlights;
  const known = ownedTextHighlights(doc);
  let snapshot = createTextSnapshot(host.textContent ?? "");
  let current: TextPresentationCommit | null = null;
  let requested = snapshot.value;
  let alive = true,
    editing = nativeTextContext(host),
    nativeOwned = false,
    baseline = true;
  let generation = 0;
  let retainedValue: string | undefined;
  let retainedEntity: unknown;
  let lease: MotionLease | null = null;
  let active = new Set<object>();
  let handoffWork = 0;
  let capturedCommit: Parameters<ReturnType<typeof createCapturedHandoff>["commit"]>[0] | null = null;
  let animations: Animation[] = [];
  let layer: HTMLElement | null = null;
  let releaseLayoutAnchor: (() => void) | null = null;
  let mask: { name: string; highlight: Highlight; sheet: CSSStyleSheet } | null = null;
  let environment: MotionEnvironment = { hidden: false, immediate: false, reduced: false, themeOwned: false };
  const signature = () =>
    chain.map((node) => {
      const css = view?.getComputedStyle(node);
      return css
        ? {
            paint: [
              css.font,
              css.color,
              css.whiteSpace,
              css.letterSpacing,
              css.wordSpacing,
              css.textTransform,
              css.textDecorationLine,
              css.fontFeatureSettings,
              css.fontVariationSettings,
              css.opacity,
              css.visibility,
              css.display,
              css.translate,
              css.scale,
              css.rotate,
              css.filter,
              css.perspective,
              css.position,
              css.overflowX,
              css.overflowY,
              css.clipPath,
              css.maskImage,
              css.backdropFilter,
              css.contentVisibility,
              css.contain,
              css.willChange,
              css.borderTopLeftRadius,
              css.borderTopRightRadius,
              css.borderBottomLeftRadius,
              css.borderBottomRightRadius,
              css.zoom,
            ].join("/"),
            width: css.width,
            height: css.height,
            transform: css.transform,
          }
        : null;
    });
  let auditFrame: number | null = null;
  let paintSignature: ReturnType<typeof signature> = [];
  const sameSignature = () => {
    const next = signature();
    return next.every((value, index) => {
      const before = paintSignature[index];
      const node = chain[index];
      if (!value || !before || !node || value.paint !== before.paint) return false;
      const geometry = current?.stripGeometry ? textGeometryProperties(node, current.cm.mode) : new Set<string>();
      return (
        ([...geometry].some((key) => /^(?:width|min-width|max-width)$/.test(key)) || value.width === before.width) &&
        ([...geometry].some((key) => /^(?:height|min-height|max-height)$/.test(key)) ||
          value.height === before.height) &&
        (geometry.has("transform") || value.transform === before.transform)
      );
    });
  };
  const plain = () => host.childNodes.length <= 1 && (!host.firstChild || host.firstChild.nodeType === 3);
  const stop = () => {
    if (auditFrame !== null) view?.cancelAnimationFrame(auditFrame);
    auditFrame = null;
    generation++;
    const old = animations;
    animations = [];
    for (const animation of old) animation.cancel();
    if (mask) {
      if (highlights?.get(mask.name) === mask.highlight) highlights.delete(mask.name);
      known.delete(mask.highlight);
      doc.adoptedStyleSheets = doc.adoptedStyleSheets.filter((sheet) => sheet !== mask?.sheet);
      mask = null;
    }
    releaseLayoutAnchor?.();
    releaseLayoutAnchor = null;
    layer?.remove();
    layer = null;
    lease?.finish();
    lease = null;
    active.clear();
    handoffWork = 0;
    capturedCommit = null;
    handoff?.cancel();
  };
  const restrictions = () => {
    const next = nativeTextContext(host);
    if (next !== editing) {
      retainedValue = !next && (nativeOwned || host.textContent !== requested) ? requested : undefined;
      retainedEntity = current?.entity;
      editing = next;
      nativeOwned = false;
      baseline = retainedValue === undefined;
      stop();
      snapshot = createTextSnapshot(host.textContent ?? "", current?.locale);
      current = null;
    }
    if (
      !plain() ||
      next ||
      selectedTextContext(host) ||
      !host.isConnected ||
      host.closest('[hidden],[inert],[aria-hidden="true"]')
    )
      stop();
  };
  const mutations = new MutationObserver((changes) => {
    if (changes.some((change) => change.type !== "attributes") || !sameSignature()) stop();
    restrictions();
    if (changes.some((change) => change.type !== "attributes")) {
      if (editing) nativeOwned = true;
      snapshot = createTextSnapshot(host.textContent ?? "", current?.locale);
      baseline = true;
    }
  });
  const chain: HTMLElement[] = [];
  const transition = (event: TransitionEvent) => {
    // Capture sees sibling/descendant feedback too. Only this host's actual
    // ancestor chain can invalidate its raster correspondence.
    if (chain.includes(event.target as HTMLElement) && !textSurfacePaint(event.propertyName)) stop();
  };
  for (let node: HTMLElement | null = host; node; node = node.parentElement) {
    chain.push(node);
    mutations.observe(node, {
      attributes: true,
      attributeFilter: ["class", "style", "hidden", "inert", "dir", "contenteditable"],
    });
    node.addEventListener("transitionrun", transition, true);
  }
  paintSignature = signature();
  mutations.observe(host, {
    attributes: true,
    attributeFilter: ["class", "style", "hidden", "inert", "dir", "contenteditable"],
    childList: true,
    characterData: true,
    subtree: true,
  });
  let expectedSize = host.getBoundingClientRect();
  const resize = new ResizeObserver(() => {
    const box = host.getBoundingClientRect();
    if (
      ["width", "height"].some(
        (axis) =>
          Math.round(box[axis as "width" | "height"] / textProofLimits.coordinateUnit) !==
          Math.round(expectedSize[axis as "width" | "height"] / textProofLimits.coordinateUnit),
      )
    )
      stop();
    expectedSize = box;
  });
  resize.observe(host);
  const selection = () => {
    if (selectedTextContext(host)) stop();
  };
  const key = (event: KeyboardEvent) => {
    if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "f") stop();
  };
  const beforeInput = () => {
    stop();
    restrictions();
  };
  doc.addEventListener("selectionchange", selection);
  doc.addEventListener("keydown", key, true);
  host.addEventListener("beforeinput", beforeInput, true);
  host.addEventListener("copy", stop, true);
  host.addEventListener("beforematch", stop);
  doc.addEventListener("scroll", stop, true);
  view?.addEventListener("resize", stop);
  view?.visualViewport?.addEventListener("resize", stop);
  view?.visualViewport?.addEventListener("scroll", stop);
  doc.fonts?.addEventListener("loadingdone", stop);
  const unsubscribe = subscribeMotionEnvironment(doc, (next) => {
    environment = next;
    if (next.hidden || next.immediate || next.reduced || next.themeOwned) stop();
  });
  const exact = (value: string, diff: ReturnType<typeof diffText>) => {
    let text = host.firstChild as Text | null;
    if (!text) {
      text = doc.createTextNode("");
      host.append(text);
    }
    const edits =
      diff.runs.length && host.textContent === snapshot.value
        ? diff.runs.map((run) => ({ start: run.before[0], end: run.before[1], insert: value.slice(...run.after) }))
        : (() => {
            let start = 0,
              end = 0;
            while (start < text.length && start < value.length && text.data[start] === value[start]) start++;
            while (
              end < text.length - start &&
              end < value.length - start &&
              text.data[text.length - 1 - end] === value[value.length - 1 - end]
            )
              end++;
            return [{ start, end: text.length - end, insert: value.slice(start, value.length - end) }];
          })();
    if (edits.every((edit) => edit.start === edit.end && edit.insert === "")) {
      snapshot = diff.snapshot;
      mutations.takeRecords();
      return text;
    }
    const selection = doc.getSelection();
    const ranges = selection
      ? Array.from({ length: selection.rangeCount }, (_, index) => {
          const range = selection.getRangeAt(index);
          return {
            range,
            start: range.startContainer,
            end: range.endContainer,
            from: range.startOffset,
            to: range.endOffset,
          };
        })
      : [];
    const endpoints =
      selection && selection.rangeCount === 1
        ? {
            anchor: selection.anchorNode,
            focus: selection.focusNode,
            from: selection.anchorOffset,
            to: selection.focusOffset,
            collapsed: selection.isCollapsed,
            forward: selection.anchorNode === ranges[0]?.start && selection.anchorOffset === ranges[0]?.from,
          }
        : null;
    const map = (offset: number, start: boolean) => {
      let delta = 0;
      for (const edit of edits) {
        if (offset < edit.start || (offset === edit.start && edit.start === edit.end && !start)) break;
        if (offset === edit.start && edit.start !== edit.end) return offset + delta;
        if (offset < edit.end) return edit.start + delta + (start ? 0 : edit.insert.length);
        delta += edit.insert.length - (edit.end - edit.start);
      }
      return offset + delta;
    };
    // Reverse changed runs preserve unchanged middle content as well as edges.
    for (const edit of [...edits].reverse())
      if (edit.start !== edit.end || edit.insert) text.replaceData(edit.start, edit.end - edit.start, edit.insert);
    // replaceData collapses a native boundary exactly at a replaced run's end.
    // Preserve retained selection/find endpoints and direction explicitly, with
    // the same Text node and no focus, editing command or synthetic input event.
    for (const saved of ranges) {
      if (saved.start === text) saved.range.setStart(text, map(saved.from, true));
      if (saved.end === text) saved.range.setEnd(text, map(saved.to, false));
    }
    if (selection && endpoints && (endpoints.anchor === text || endpoints.focus === text))
      selection.setBaseAndExtent(
        endpoints.anchor as Node,
        endpoints.anchor === text ? map(endpoints.from, endpoints.collapsed || endpoints.forward) : endpoints.from,
        endpoints.focus as Node,
        endpoints.focus === text ? map(endpoints.to, endpoints.collapsed || !endpoints.forward) : endpoints.to,
      );
    snapshot = diff.snapshot;
    mutations.takeRecords();
    expectedSize = host.getBoundingClientRect();
    paintSignature = signature();
    return text;
  };
  const available = () =>
    Boolean(
      view?.Highlight &&
        view.CSSStyleSheet &&
        highlights &&
        host.getRootNode() === doc &&
        highlights.size <= motionLimits.changedGraphemes &&
        [...highlights.values()].every((highlight) => known.has(highlight)),
    );
  return {
    commit(options: TextPresentationCommit) {
      if (!alive) {
        options.capture?.dispose();
        return;
      }
      restrictions();
      const { value, revision, cm } = options;
      const sameEntity = current !== null && Object.is(options.entity, current.entity);
      const previous = current;
      const clock = cm.parameters(binding);
      const transfer = cm.parameters(bindMotionParameters(handoffValue, "handoff/value"));
      const transferClock = transfer.kind === "handoff" ? transfer.spatial : { duration: 0 };
      if (!editing && retainedValue !== undefined) {
        if (value === retainedValue && Object.is(options.entity, retainedEntity)) {
          current = options;
          options.capture?.dispose();
          return;
        }
        retainedValue = undefined;
        if (!Object.is(options.entity, retainedEntity)) baseline = true;
      }
      if (editing && host.textContent !== (previous ? requested : (options.nativeBaseline ?? requested)))
        nativeOwned = true;
      current = options;
      if (editing && nativeOwned) {
        requested = value;
        stop();
        options.capture?.dispose();
        return;
      }
      if (previous?.revision === revision && value === requested && sameEntity) {
        if (
          !revision.current() ||
          cm.mode === "none" ||
          options.granularity !== previous.granularity ||
          options.locale !== previous.locale ||
          options.stripGeometry !== previous.stripGeometry ||
          cm.timeScale === 0 ||
          options.visible === false ||
          clock.kind !== "text" ||
          Number(clock.enter.duration) === 0
        )
          stop(); // live-text-policy
        else if (layer && (cm.reduced !== previous.cm.reduced || cm.mode !== previous.cm.mode)) {
          const nextSignature = signature();
          const box = host.getBoundingClientRect();
          if (
            !lease?.current() ||
            nextSignature.some((value, index) => !value || value.paint !== paintSignature[index]?.paint) ||
            (["width", "height"] as const).some(
              (axis) =>
                Math.round(box[axis] / textProofLimits.coordinateUnit) !==
                Math.round(expectedSize[axis] / textProofLimits.coordinateUnit),
            ) ||
            !proveTextLayout(host, snapshot, {
              surfacePaint: true,
              geometryMode: options.stripGeometry ? cm.mode : undefined,
            })
          ) {
            stop();
            return;
          }
          // A compound downgrade has already released its spatial overlay in
          // before-layout. Accept that proven final allocation, never arbitrary
          // paint changes, before the pending ancestor mutation audit runs.
          expectedSize = box;
          paintSignature = nextSignature;
          mutations.takeRecords();
          // A permitted opacity flight survives a live policy edit. Capture
          // actual paint before cancelling its old clock; discard all stagger
          // delays and keep the current native mask and destination.
          const paints = [...layer.querySelectorAll("canvas")];
          const from = paints.map((canvas) => view?.getComputedStyle(canvas).opacity ?? "1");
          const old = animations;
          const epoch = ++generation;
          animations = [];
          for (const animation of old) animation.cancel();
          try {
            for (const [index, canvas] of paints.entries()) {
              const entering = canvas.dataset.cadenceTextKind === "enter";
              const transition = entering ? clock.enter : clock.exit;
              animations.push(
                canvas.animate([{ opacity: from[index] }, { opacity: entering ? 1 : 0 }], {
                  duration: motionMilliseconds(Number(transition.duration)),
                  delay: 0,
                  easing: `cubic-bezier(${cm.scope.tokens.ease[entering ? "out" : "in"].join(",")})`,
                  fill: "both",
                }),
              );
            }
          } catch {
            stop();
            return;
          }
          void Promise.allSettled(animations.map((animation) => animation.finished)).then(() => {
            if (alive && generation === epoch && lease?.current()) stop();
          });
        }
        if (capturedCommit) handoff?.commit({ ...capturedCommit, transition: transferClock, immediate: cm.reduced });
        if (options.capture !== previous.capture) options.capture?.dispose();
        return;
      }
      const changed = value !== requested;
      requested = value;
      if (!plain() || host.matches("input,textarea,select,option")) {
        stop();
        options.capture?.dispose();
        return;
      }
      const diff = diffText(snapshot, value, options.locale);
      const units = diff.runs.flatMap((run) => [...run.outgoing, ...run.incoming]);
      const proposed = new Set(units.map((unit) => unit.identity));
      const union = new Set([...active, ...proposed]);
      const others = [...transaction.activeWork("changedGraphemes")].reduce(
        (sum, [entity, work]) => sum + (entity === host ? 0 : work),
        -handoffWork,
      );
      const overflow =
        boundTextRevision([diff], active)[0]?.immediate === "changed" ||
        union.size + others > motionLimits.changedGraphemes;
      if (overflow)
        registration.begin(revision, ["text.change"], { changedGraphemes: motionLimits.changedGraphemes + 1 }, stop);
      stop();
      const canAnimate =
        revision.current() &&
        sameEntity &&
        changed &&
        !baseline &&
        !diff.immediate &&
        !overflow &&
        options.visible !== false &&
        !editing &&
        !selectedTextContext(host) &&
        !environment.hidden &&
        !environment.immediate &&
        !environment.themeOwned &&
        !(environment.reduced && !cm.reduced) &&
        cm.mode !== "none" &&
        cm.timeScale !== 0 &&
        clock.kind === "text" &&
        Number(clock.enter.duration) > 0 &&
        available();
      const geometryMode = options.stripGeometry ? cm.mode : undefined;
      const before = canAnimate ? proveTextLayout(host, snapshot, { surfacePaint: true, geometryMode }) : null;
      const text = exact(value, diff);
      if (!sameEntity) snapshot = createTextSnapshot(value, options.locale);
      baseline = false;
      const after = before && proveTextLayout(host, snapshot, { surfacePaint: true, geometryMode });
      mutations.takeRecords();
      const proof =
        before &&
        after &&
        shapeTextDiff(diff, {
          // Actual-font raster correspondence proves every boundary. Range boxes
          // supply the unchanged native layout; no semantic split tree is made.
          before: new Set(diff.runs.flatMap((run) => [...run.before])),
          after: new Set(diff.runs.flatMap((run) => [...run.after])),
        });
      if (!proof || proof.immediate || clock.kind !== "text" || !view || !highlights) {
        options.capture?.dispose();
        handoff?.commit({
          revision,
          capture: null,
          destination: host,
          transition: transferClock,
          immediate: cm.reduced,
          sourceRetired: true,
          current: () => alive && current?.revision === revision,
          fallback() {},
          terminal() {},
        });
        return;
      }
      const incoming = diff.runs.flatMap((run) => run.incoming),
        outgoing = diff.runs.flatMap((run) => run.outgoing);
      const local = () => {
        handoffWork = 0;
        if (!alive || !revision.current()) return;
        lease = registration.begin(revision, ["text.change"], { changedGraphemes: units.length }, stop);
        if (!lease?.current()) return;
        active = proposed;
        const epoch = generation;
        const word = options.granularity === "word";
        const groups = changedTextGroups(snapshot, incoming, word, options.locale);
        if (!groups) {
          stop();
          return;
        }
        const groupCount = new Set(groups.values()).size;
        const rhythm = resolveStaggerParameters(
          groupCount,
          word ? "word" : "char",
          cm.mode,
          cm.timeScale,
          cm.scope.tokens,
        );
        const last = Math.max(0, Math.min(units.length, motionLimits.staggerElements) - 1);
        // Standalone text keeps the stricter final character-delay cap in word mode too.
        const step = Math.min(rhythm.step, last ? motionLimits.characterDelay / last : 0);
        const moving =
          options.characterStagger && !cm.reduced
            ? resolveStaggerParameters(units.length, "char", cm.mode, cm.timeScale, cm.scope.tokens)
            : { moving: units.length, step: 0 };
        const ranges: Range[] = [];
        let pixels = 0,
          movingIndex = 0;
        const paints: { canvas: HTMLCanvasElement; incoming: boolean; index: number }[] = [];
        const add = (unit: (typeof incoming)[number], entering: boolean) => {
          if (movingIndex >= moving.moving) return;
          const layout = entering ? after : before;
          const box = layout.boxes.get(unit.identity);
          if (
            !box ||
            box.width <= 0 ||
            box.left < 0 ||
            box.top < 0 ||
            box.left + box.width > view.innerWidth ||
            box.top + box.height > view.innerHeight ||
            chain.some((node) => {
              const css = view.getComputedStyle(node);
              if (!/(auto|scroll|hidden|clip)/.test(`${css.overflowX} ${css.overflowY}`)) return false;
              const clip = node.getBoundingClientRect();
              return (
                box.left < clip.left ||
                box.top < clip.top ||
                box.left + box.width > clip.right ||
                box.top + box.height > clip.bottom
              );
            })
          )
            return;
          const canvas = outgoingTextPaint(host, unit, layout);
          if (!canvas) return;
          pixels += canvas.width * canvas.height;
          if (pixels > textProofLimits.pixels) return;
          canvas.dataset.cadenceTextKind = entering ? "enter" : "exit";
          canvas.dataset.motion = cm.mode;
          paints.push({ canvas, incoming: entering, index: groups.get(unit.identity) ?? 0 });
          movingIndex++;
          if (entering) {
            let offset = 0;
            for (const item of snapshot.units ?? []) {
              if (item.identity === unit.identity) break;
              offset += item.text.length;
            }
            const range = doc.createRange();
            range.setStart(text, offset);
            range.setEnd(text, offset + unit.text.length);
            ranges.push(range);
          }
        };
        for (const unit of outgoing) add(unit, false);
        for (const unit of incoming) add(unit, true);
        if (!paints.length) {
          stop();
          return;
        }
        try {
          if (ranges.length) {
            const name = `cadence-text-${++nextMask}`;
            const sheet = new view.CSSStyleSheet();
            sheet.replaceSync(`::highlight(${name}) { color: transparent; }`);
            const highlight = new view.Highlight(...ranges);
            mask = { name, sheet, highlight };
            known.add(highlight);
            doc.adoptedStyleSheets = [...doc.adoptedStyleSheets, sheet];
            highlights.set(name, highlight);
            if (view.getComputedStyle(host, `::highlight(${name})`).color !== "rgba(0, 0, 0, 0)") {
              stop();
              return;
            }
          }
          layer = doc.createElement("span");
          layer.inert = true;
          layer.setAttribute("aria-hidden", "true");
          layer.dataset.cadenceTextLayer = "";
          layer.dataset.cadenceTextOwner = host.id;
          layer.dataset.motion = cm.mode;
          Object.assign(layer.style, {
            position: "fixed",
            inset: "0",
            contain: "strict",
            overflow: "clip",
            pointerEvents: "none",
            userSelect: "none",
            overflowAnchor: "none",
            scrollSnapAlign: "none",
          });
          for (const item of paints) layer.append(item.canvas);
          doc.body.append(layer);
          releaseLayoutAnchor = followTextLayout(host, layer, stop);
          if (!releaseLayoutAnchor) throw new Error("Native display anchor unavailable");
          const audit = () => {
            auditFrame = null;
            if (!alive || !layer || !lease?.current() || !current) {
              stop();
              return;
            }
            let count = 0;
            for (const node of chain) {
              if (!node.getAnimations) {
                stop();
                return;
              }
              const handles = node.getAnimations();
              count += handles.length;
              if (
                count > motionLimits.collectionVisuals ||
                handles.some(
                  (animation) => !knownTextGeometry(animation, current?.cm.mode) && !surfaceOnlyAnimation(animation),
                )
              ) {
                stop();
                return;
              }
            }
            auditFrame = view.requestAnimationFrame(audit);
          };
          if (options.stripGeometry) auditFrame = view.requestAnimationFrame(audit);
          for (const { canvas, incoming: entering, index } of paints) {
            const transition = entering ? clock.enter : clock.exit;
            const animation = canvas.animate(
              entering ? [{ opacity: 0 }, { opacity: 1 }] : [{ opacity: 1 }, { opacity: 0 }],
              {
                duration: motionMilliseconds(Number(transition.duration)),
                delay: motionMilliseconds(entering && options.characterStagger && !cm.reduced ? step * index : 0),
                easing: `cubic-bezier(${cm.scope.tokens.ease[entering ? "out" : "in"].join(",")})`,
                fill: "both",
              },
            );
            animations.push(animation);
          }
          void Promise.allSettled(animations.map((animation) => animation.finished)).then(() => {
            if (alive && generation === epoch && lease?.current()) stop();
          });
        } catch {
          stop();
        } // Unsupported/CSP/native failure never leaves hidden text.
      };
      // The same shaped native snapshot proves the one contiguous incoming run.
      // Only that Range is concealed; retained glyphs remain ordinary native ink.
      const run = diff.runs.length === 1 ? diff.runs[0] : null;
      if (
        handoff &&
        options.capture &&
        run &&
        incoming.length > 0 &&
        options.capture.text === run.incoming.map((unit) => unit.text).join("")
      ) {
        const range = doc.createRange();
        range.setStart(text, run.after[0]);
        range.setEnd(text, run.after[1]);
        const epoch = generation;
        active = proposed;
        handoffWork = incoming.length;
        capturedCommit = {
          revision,
          capture: options.capture,
          destination: host,
          transition: transferClock,
          immediate: cm.reduced,
          sourceRetired: options.sourceRetired ?? false,
          current: () => alive && current?.revision === revision && options.visible !== false,
          fallback: local,
          terminal: () => {
            if (generation === epoch) {
              active.clear();
              handoffWork = 0;
              capturedCommit = null;
            }
          },
          slot: "text-handoff-paint",
          run:
            !options.deferHandoff && options.capture.text === value
              ? undefined
              : {
                  current: () =>
                    host.firstChild === text &&
                    host.textContent === value &&
                    range.toString() === options.capture?.text,
                  bounds: () => range.getBoundingClientRect(),
                  conceal() {
                    const name = `cadence-text-${++nextMask}`;
                    const sheet = new view.CSSStyleSheet();
                    sheet.replaceSync(`::highlight(${name}) { color: transparent; }`);
                    const highlight = new view.Highlight(range);
                    const release = () => {
                      if (highlights.get(name) === highlight) highlights.delete(name);
                      known.delete(highlight);
                      doc.adoptedStyleSheets = doc.adoptedStyleSheets.filter((candidate) => candidate !== sheet);
                    };
                    try {
                      known.add(highlight);
                      doc.adoptedStyleSheets = [...doc.adoptedStyleSheets, sheet];
                      highlights.set(name, highlight);
                      if (view.getComputedStyle(host, `::highlight(${name})`).color === "rgba(0, 0, 0, 0)")
                        return release;
                    } catch {
                      /* Native/CSP failure exposes exact current text. */
                    }
                    release();
                    return null;
                  },
                },
        };
        const accepted = capturedCommit;
        const transfer = () => {
          if (alive && capturedCommit === accepted && generation === epoch) handoff.commit(accepted);
          else options.capture?.dispose();
        };
        if (options.deferHandoff) queueMicrotask(transfer);
        else transfer();
        return;
      }
      options.capture?.dispose();
      local();
    },
    cancel: stop,
    dispose() {
      if (!alive) return;
      alive = false;
      stop();
      if (sharedHandoff) handoff?.cancel();
      else handoff?.dispose();
      registration.dispose();
      mutations.disconnect();
      resize.disconnect();
      unsubscribe();
      doc.removeEventListener("selectionchange", selection);
      doc.removeEventListener("keydown", key, true);
      host.removeEventListener("beforeinput", beforeInput, true);
      host.removeEventListener("copy", stop, true);
      host.removeEventListener("beforematch", stop);
      doc.removeEventListener("scroll", stop, true);
      view?.removeEventListener("resize", stop);
      view?.visualViewport?.removeEventListener("resize", stop);
      view?.visualViewport?.removeEventListener("scroll", stop);
      doc.fonts?.removeEventListener("loadingdone", stop);
      for (const node of chain) node.removeEventListener("transitionrun", transition, true);
    },
  };
}

"use client";

import { useEffect, useInsertionEffect, useLayoutEffect, useRef } from "react";
import type { createCapturedHandoff } from "./captured-handoff";
import type { MotionHostRef } from "./motion-ref";
import { createMotionTransaction } from "./motion-transaction";
import type { CadenceMotion } from "./provider";
import { createTextPresentation, type TextPresentationCommit } from "./text-presentation";

const committed = typeof window === "undefined" ? useEffect : useLayoutEffect;

/** One native Text node. A compound display may switch its controller without replacing the host. */
export function useTextPresentation(
  host: MotionHostRef<HTMLElement>,
  value: string,
  cm: CadenceMotion,
  entity: unknown,
  options: Partial<
    Pick<
      TextPresentationCommit,
      | "locale"
      | "granularity"
      | "characterStagger"
      | "visible"
      | "capture"
      | "sourceRetired"
      | "deferHandoff"
      | "nativeBaseline"
      | "stripGeometry"
    >
  > & { enabled?: boolean; initialText?: string } = {},
  supplied?: ReturnType<typeof createMotionTransaction>,
  handoff?: ReturnType<typeof createCapturedHandoff>,
) {
  const initial = useRef(options.initialText ?? value);
  const local = useRef<ReturnType<typeof createMotionTransaction> | null>(null);
  if (!local.current) local.current = createMotionTransaction();
  const transaction = supplied ?? local.current;
  type Connection = {
    element: HTMLElement;
    host: MotionHostRef<HTMLElement>;
    identity: object | undefined;
    transaction: typeof transaction;
    controller: ReturnType<typeof createTextPresentation>;
    source: object;
    dispose(): void;
  };
  const connected = useRef<Connection | null>(null);
  const enabled = options.enabled !== false;
  // Retire the previous form before any successor's layout commit can allocate paint.
  useInsertionEffect(() => {
    if (!enabled) connected.current?.dispose();
  }, [enabled]);
  committed(() => {
    if (!enabled) {
      connected.current?.dispose();
      return;
    }
    const old = connected.current;
    if (
      old &&
      (old.host !== host ||
        old.element !== host.current ||
        old.identity !== host.identity ||
        old.transaction !== transaction)
    )
      old.dispose();
    if (!connected.current && host.current) {
      const connection: Connection = {
        element: host.current,
        host,
        identity: host.identity,
        transaction,
        controller: createTextPresentation(host.current, transaction, handoff, Boolean(handoff)),
        source: {},
        dispose() {
          if (connected.current === connection) connected.current = null;
          if (host.invalidate === connection.dispose) host.invalidate = undefined;
          connection.controller.dispose();
        },
      };
      connected.current = connection;
    }
    const connection = connected.current;
    if (!connection) return;
    host.invalidate = connection.dispose;
    connection.controller.commit({
      ...options,
      value,
      entity,
      cm,
      characterStagger: cm.reduced ? false : options.characterStagger,
      revision: transaction.revision("content", value, connection.source),
    });
  });
  committed(() => () => connected.current?.dispose(), []);
  return initial.current;
}
